{
  "name": "@y00njinuk/opencode-claude-auth",
  "version": "2.2.6",
  "description": "OpenCode plugin that uses your Claude Code credentials — no separate login needed. Fork of opencode-claude-auth with a configurable proactive refresh window.",
  "keywords": [
    "anthropic",
    "auth",
    "claude",
    "opencode",
    "plugin"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/y00njinuk/opencode-claude-auth.git"
  },
  "files": [
    "opencode-claude-auth.js",
    "dist",
    "installation.md"
  ],
  "type": "module",
  "main": "opencode-claude-auth.js",
  "module": "opencode-claude-auth.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./opencode-claude-auth.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./opencode-claude-auth.js"
    },
    "./claude-auth-plugin": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./claude-auth-plugin.js": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./opencode-claude-auth": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./opencode-claude-auth.js": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@types/node": "^25.5.0",
    "oxfmt": "0.41.0",
    "oxlint": "1.56.0",
    "typescript": "^5.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "scripts": {
    "build": "rm -rf dist && tsc && cp src/anthropic-prompt.txt dist/",
    "test": "node --test --experimental-strip-types src/**/*.test.ts scripts/**/*.test.ts",
    "test:models": "pnpm run build && node scripts/test-models.ts",
    "test:headless": "pnpm run build && node --experimental-strip-types scripts/test-headless.ts",
    "intercept": "pnpm run build && node --experimental-strip-types scripts/intercept-claude.ts",
    "intercept:all": "pnpm run build && node --experimental-strip-types scripts/intercept-claude.ts --all",
    "intercept:update": "pnpm run build && node --experimental-strip-types scripts/intercept-claude.ts --all --update",
    "lint": "oxlint && oxfmt --check .",
    "lint:fix": "oxlint --fix . && oxfmt --write .",
    "format": "oxfmt --write ."
  }
}
